// ============================================================================
// FreeLang ORM 모듈 - Repository 패턴 기반 CRUD 추상화
// ============================================================================
// 목표: schema.fl + query.fl을 사용해 Repository 패턴 제공
// 원리:
//   1. Repository: 특정 Table을 감싸는 CRUD 추상화
//   2. find_by_*: 단일 조건 쿼리 단순화
//   3. repo_update: 컬럼 이름으로 업데이트
// 구조:
//   - Repository 구조체
//   - 팩토리 함수
//   - CRUD 함수
//   - 단순화된 검색 함수
// ============================================================================

module orm {
    // === 에러 코드 ===
    const ORM_OK:          i32 = 0;
    const ORM_ERR_NOTFOUND: i32 = 30;
    const ORM_ERR_FULL:    i32 = 31;
    const ORM_ERR_COL:     i32 = 32;

    // === 데이터 구조체 ===

    struct Repository {
        table: schema.Table;
        name:  string;
    }

    // === 팩토리 함수 ===

    func repo_new(s: schema.TableSchema) -> Repository {
        return Repository{
            table: schema.table_new(s),
            name:  s.name,
        };
    }

    // === 기본 CRUD ===

    // INSERT
    func (r: *Repository) repo_insert(row: schema.RecordRow) -> (i64, bool) {
        return r.table.table_insert(row);
    }

    // SELECT by ID
    func (r: *Repository) repo_find_by_id(id: i64) -> (schema.RecordRow, bool) {
        return r.table.table_get(id);
    }

    // SELECT ALL (삭제되지 않은 행 전체)
    func (r: *Repository) repo_find_all() -> query.QueryResult {
        let q = query.query_table(r.table);
        return query.execute(r.table, q);
    }

    // SELECT with int WHERE
    func (r: *Repository) repo_find_where_int(col_idx: i32, op: i32, val: i64) -> query.QueryResult {
        let q = query.query_table(r.table);
        q.where_int(col_idx, op, val);
        return query.execute(r.table, q);
    }

    // SELECT with str WHERE
    func (r: *Repository) repo_find_where_str(col_idx: i32, op: i32, val: string) -> query.QueryResult {
        let q = query.query_table(r.table);
        q.where_str(col_idx, op, val);
        return query.execute(r.table, q);
    }

    // SELECT with ORDER BY int
    func (r: *Repository) repo_find_ordered_int(col_idx: i32, asc: bool, lim: i32) -> query.QueryResult {
        let q = query.query_table(r.table);
        q.order_by_int(col_idx, asc);
        q.set_limit(lim);
        return query.execute(r.table, q);
    }

    // UPDATE int 컬럼
    func (r: *Repository) repo_update_int(id: i64, col_idx: i32, val: i64) -> bool {
        return r.table.table_update_int(id, col_idx, val);
    }

    // UPDATE str 컬럼
    func (r: *Repository) repo_update_str(id: i64, col_idx: i32, val: string) -> bool {
        return r.table.table_update_str(id, col_idx, val);
    }

    // UPDATE bool 컬럼
    func (r: *Repository) repo_update_bool(id: i64, col_idx: i32, val: bool) -> bool {
        return r.table.table_update_bool(id, col_idx, val);
    }

    // UPDATE by 컬럼 이름
    func (r: *Repository) repo_update_by_name_int(id: i64, col_name: string, val: i64) -> (i32, bool) {
        let col_idx, found = r.table.schema.schema_find_col(col_name);
        if !found {
            return (ORM_ERR_COL, false);
        }
        let ok = r.table.table_update_int(id, col_idx, val);
        return (ORM_OK, ok);
    }

    func (r: *Repository) repo_update_by_name_str(id: i64, col_name: string, val: string) -> (i32, bool) {
        let col_idx, found = r.table.schema.schema_find_col(col_name);
        if !found {
            return (ORM_ERR_COL, false);
        }
        let ok = r.table.table_update_str(id, col_idx, val);
        return (ORM_OK, ok);
    }

    // DELETE (소프트 삭제)
    func (r: *Repository) repo_delete(id: i64) -> bool {
        return r.table.table_delete(id);
    }

    // COUNT (전체 살아있는 행)
    func (r: *Repository) repo_count() -> i32 {
        return r.table.table_count();
    }

