        let q = query.query_table(r.table);
        q.where_int(col_idx, op, val);
        q.set_aggregate(query.AGG_COUNT, 0);
        let result = query.execute(r.table, q);
        return result.agg_value;
    }

    // SUM
    func (r: *Repository) repo_sum(col_idx: i32) -> i64 {
        let q = query.query_table(r.table);
        q.set_aggregate(query.AGG_SUM, col_idx);
        let result = query.execute(r.table, q);
        return result.agg_value;
    }

    // MAX
    func (r: *Repository) repo_max(col_idx: i32) -> i64 {
        let q = query.query_table(r.table);
        q.set_aggregate(query.AGG_MAX, col_idx);
        let result = query.execute(r.table, q);
        return result.agg_value;
    }

    // MIN
    func (r: *Repository) repo_min(col_idx: i32) -> i64 {
        let q = query.query_table(r.table);
        q.set_aggregate(query.AGG_MIN, col_idx);
        let result = query.execute(r.table, q);
        return result.agg_value;
    }

    // 페이징 조회
    func (r: *Repository) repo_page(page: i32, page_size: i32) -> query.QueryResult {
        let q = query.query_table(r.table);
        q.set_offset(page * page_size);
        q.set_limit(page_size);
        return query.execute(r.table, q);
    }

    // === 결과 유틸리티 ===

    // QueryResult에서 특정 행의 RecordRow 가져오기
    func (r: *Repository) result_get_row(result: query.QueryResult, result_idx: i32) -> (schema.RecordRow, bool) {
        if result_idx < 0 || result_idx >= result.row_count {
            return (schema.record_new(), false);
        }
        let row_idx = result.row_indices[result_idx];
        return (r.table.table_get_row(row_idx), true);
    }

    // === 통계 ===

    func (r: *Repository) repo_stats() -> string {
        let stats = r.table.table_stats();
        return "[Repo " + r.name + "] " + stats;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let rr = n % 10;
        return i32_to_str(d) + i32_to_str(rr);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

